import { EventEmitter } from 'events';

interface CacheEntry {
  value: Buffer;
  refCount: number;
  poolSlot: number;
  released: boolean;
}

class BufferPool {
  private slots: (Buffer | null)[];
  private freeList: number[];
  private freedSet: Set<number>;

  constructor(private slotSize: number, private poolSize: number) {
    this.slots = new Array(poolSize).fill(null);
    this.freeList = Array.from({ length: poolSize }, (_, i) => i);
    this.freedSet = new Set(this.freeList);
  }

  acquire(): { buffer: Buffer; slot: number } | null {
    if (this.freeList.length === 0) return null;
    const slot = this.freeList.pop()!;
    this.freedSet.delete(slot);
    this.slots[slot] = Buffer.alloc(this.slotSize);
    return { buffer: this.slots[slot]!, slot };
  }

  release(slot: number): void {
    if (slot < 0 || slot >= this.poolSize) return;
    if (this.freedSet.has(slot)) return;
    this.slots[slot] = null;
    this.freeList.push(slot);
    this.freedSet.add(slot);
  }

  getBuffer(slot: number): Buffer | null {
    return this.slots[slot];
  }
}

class RateLimiter {
  private tokens: number;
  private lastRefill: number;

  constructor(private maxTokens: number, private refillRate: number) {
    this.tokens = maxTokens;
    this.lastRefill = Date.now();
  }

  tryAcquire(): boolean {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    this.tokens = Math.min(this.maxTokens, this.tokens + Math.floor(elapsed * this.refillRate / 1000));
    this.lastRefill = now;
  }
}

class DistributedCacheClient extends EventEmitter {
  private pool: BufferPool;
  private limiter: RateLimiter;
  private entries: Map<string, CacheEntry>;
  private pendingRetries: Map<string, NodeJS.Timeout>;
  private maxRetries: number = 3;

  constructor(poolSize: number = 64, slotSize: number = 4096) {
    super();
    this.pool = new BufferPool(slotSize, poolSize);
    this.limiter = new RateLimiter(100, 50);
    this.entries = new Map();
    this.pendingRetries = new Map();
  }

  async get(key: string): Promise<Buffer | null> {
    const entry = this.entries.get(key);
    if (entry && !entry.released) {
      entry.refCount++;
      return this.pool.getBuffer(entry.poolSlot);
    }
    return this.fetchWithRetry(key, 0);
  }

  private async fetchWithRetry(key: string, attempt: number): Promise<Buffer | null> {
    if (attempt >= this.maxRetries) {
      this.cleanupEntry(key);
      return null;
    }

    if (!this.limiter.tryAcquire()) {
      return new Promise((resolve) => {
        const timeout = setTimeout(() => {
          this.pendingRetries.delete(key);
          resolve(this.fetchWithRetry(key, attempt));
        }, 100 * Math.pow(2, attempt));
        this.pendingRetries.set(key, timeout);
      });
    }

    try {
      const data = await this.simulateNetworkFetch(key);
      return this.storeInPool(key, data);
    } catch (err) {
      return this.fetchWithRetry(key, attempt + 1);
    }
  }

  private storeInPool(key: string, data: Buffer): Buffer | null {
    const existing = this.entries.get(key);
    if (existing && !existing.released) {
      this.releaseEntry(existing);
    }

    const acquired = this.pool.acquire();
    if (!acquired) return null;

    data.copy(acquired.buffer);
    this.entries.set(key, {
      value: acquired.buffer,
      refCount: 1,
      poolSlot: acquired.slot,
      released: false
    });
    return acquired.buffer;
  }

  release(key: string): void {
    const entry = this.entries.get(key);
    if (!entry) return;
    if (entry.released) return;

    entry.refCount--;
    if (entry.refCount <= 0) {
      this.releaseEntry(entry);
    }
  }

  private releaseEntry(entry: CacheEntry): void {
    if (entry.released) return;
    this.pool.release(entry.poolSlot);
    entry.released = true;
  }

  private cleanupEntry(key: string): void {
    const entry = this.entries.get(key);
    if (!entry) return;
    this.releaseEntry(entry);
    this.entries.delete(key);
  }

  async evict(key: string): Promise<void> {
    const pending = this.pendingRetries.get(key);
    if (pending) {
      clearTimeout(pending);
      this.pendingRetries.delete(key);
    }

    const entry = this.entries.get(key);
    if (entry) {
      this.releaseEntry(entry);
      this.entries.delete(key);
    }
  }

  async refresh(key: string): Promise<Buffer | null> {
    const entry = this.entries.get(key);
    if (entry) {
      this.releaseEntry(entry);
    }
    return this.fetchWithRetry(key, 0);
  }

  private async simulateNetworkFetch(key: string): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (Math.random() < 0.3) {
          reject(new Error('Network timeout'));
        } else {
          resolve(Buffer.from(`cached_${key}_${Date.now()}`));
        }
      }, 10);
    });
  }
}

export { DistributedCacheClient, BufferPool, RateLimiter };
